#!/usr/bin/env bash
set -euo pipefail
echo "== 解包证书功能文件 =="
mkdir -p /tmp/xm-cert && rm -rf /tmp/xm-cert/site && mkdir -p /tmp/xm-cert/site
echo '' | base64 -d > /tmp/xm-cert/u.tgz
tar -xzf /tmp/xm-cert/u.tgz -C /tmp/xm-cert/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-cert/site/. /var/www/xinmo-site/
echo "== 校验 =="
ls -l /var/www/xinmo-site/certificates.html
ls -l /var/www/xinmo-site/assets/js/certificates-data.js
grep -c 'data-cert-nav' /var/www/xinmo-site/index.html
echo "== DONE =="
